// Command schemagen extracts migration DDL from an oracle database.
//
// The output is upstream's own schema verbatim (sqlite_master), never
// hand-written: for SQLite, `schemagen -db <oracle.sqlite> -out <file>`.
// Postgres DDL comes from the oracle's PG database via pg_dump (see
// scripts/pg-oracle.sh) because pg_catalog does not store textual DDL.
//
// The digest gate (schemadigest) — not the generator — owns the truth: a
// regenerated file that drifts from a migrated database fails the pair.
package main

import (
	"database/sql"
	"flag"
	"fmt"
	"os"
	"strings"

	_ "modernc.org/sqlite"

	"doory-go/internal/schema"
)

func main() {
	dbPath := flag.String("db", ".oracle/oracle.sqlite3", "oracle sqlite database")
	out := flag.String("out", "", "output migration file")
	flag.Parse()

	if *out == "" {
		fmt.Fprintln(os.Stderr, "schemagen: -out is required")
		os.Exit(2)
	}
	db, err := sql.Open("sqlite", *dbPath)
	if err != nil {
		fatal(err)
	}
	defer db.Close()

	stmts, err := schema.ExtractSQLiteDDL(db)
	if err != nil {
		fatal(err)
	}

	var b strings.Builder
	fmt.Fprintf(&b, "-- Generated by pnpm schemagen from the pinned oracle (%s).\n", *dbPath)
	b.WriteString("-- Upstream's schema verbatim: never hand-edit; regenerate and let\n")
	b.WriteString("-- schemadigest prove the migrated databases match, per dialect (D4).\n\n")
	for _, stmt := range stmts {
		b.WriteString(stmt)
		b.WriteString("\n")
	}
	if err := os.MkdirAll(dirOf(*out), 0o755); err != nil {
		fatal(err)
	}
	if err := os.WriteFile(*out, []byte(b.String()), 0o644); err != nil {
		fatal(err)
	}
	fmt.Printf("schemagen: %d statements -> %s\n", len(stmts), *out)
}

func dirOf(p string) string {
	if i := strings.LastIndexByte(p, '/'); i >= 0 {
		return p[:i]
	}
	return "."
}

func fatal(err error) {
	fmt.Fprintln(os.Stderr, "schemagen:", err)
	os.Exit(1)
}
